        {/* Action Controls for Assistant Messages */}
        {isAssistant && !isStreaming && (
          <div className="flex items-center gap-1 pt-2 border-t border-border/40 text-muted-foreground">
            <button
              type="button"
              onClick={handleCopy}
              aria-label={copied ? "Copied message" : "Copy message"}
