            <button
              type="button"
              onClick={() => handleFeedback("down")}
              aria-label="Thumbs down poor response"
              className={cn(
                "p-1 rounded-md text-xs hover:bg-muted transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring",
