                        stroke="currentColor"
                        strokeWidth="1.5"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        className="text-primary"
                        points={m.sparkline
                          .map((val, idx) => {
                            const min = Math.min(...m.sparkline);
                            const max = Math.max(...m.sparkline) || 1;
                            const x = (idx / (m.sparkline.length - 1)) * 64;
                            const y = 18 - ((val - min) / (max - min || 1)) * 16;
                            return `${x},${y}`;
                          })
                          .join(" ")}
                      />
                    </svg>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
