const MODELS = [
  { id: "claude-3-7-sonnet", name: "Claude 3.7 Sonnet", badge: "Smartest" },
  { id: "gpt-4o", name: "GPT-4o", badge: "Fast" },
  { id: "gemini-2-5-pro", name: "Gemini 2.5 Pro", badge: "1M Context" },
