              ? Database
              : Cpu;

          return (
            <React.Fragment key={stage.id}>
              <motion.div
                onClick={() => setActiveStageId(stage.id)}
                onKeyDown={(e) => {
                  if (e.key === "Enter" || e.key === " ") {
                    e.preventDefault();
                    setActiveStageId(stage.id);
